import { randomUUID } from "node:crypto";
import { mkdirSync } from "node:fs";
import { dirname } from "node:path";
import { DatabaseSync } from "node:sqlite";
import type { CreateYoutubeJob, YoutubeJob, YoutubeJobStatus } from "./types.js";
type Row = { sequence:number; id:string; request_id:string; chat_id:string; user_id:string; log_id:string; url:string; status:YoutubeJobStatus; created_at:number; updated_at:number; finished_at:number|null; error_code:string|null; artifact_path:string|null; artifact_bytes:number|null; artifact_sha256:string|null; };
const map=(r:Row):YoutubeJob=>({ sequence:+r.sequence,id:r.id,requestId:r.request_id,chatId:r.chat_id,userId:r.user_id,logId:r.log_id,url:r.url,status:r.status,createdAt:r.created_at,updatedAt:r.updated_at,finishedAt:r.finished_at??undefined,errorCode:r.error_code??undefined,artifactPath:r.artifact_path??undefined,artifactBytes:r.artifact_bytes??undefined,artifactSha256:r.artifact_sha256??undefined });
export class YoutubeJobStore { #db:DatabaseSync;
 constructor(file:string){ mkdirSync(dirname(file),{recursive:true,mode:0o700}); this.#db=new DatabaseSync(file); this.#db.exec(`PRAGMA journal_mode=WAL; CREATE TABLE IF NOT EXISTS jobs(sequence INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT UNIQUE NOT NULL,request_id TEXT UNIQUE NOT NULL,chat_id TEXT NOT NULL,user_id TEXT NOT NULL,log_id TEXT NOT NULL,url TEXT NOT NULL,status TEXT NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,finished_at INTEGER,error_code TEXT,artifact_path TEXT,artifact_bytes INTEGER,artifact_sha256 TEXT); CREATE INDEX IF NOT EXISTS youtube_queue ON jobs(status,sequence); CREATE INDEX IF NOT EXISTS youtube_room ON jobs(chat_id,status);`); this.#db.prepare("UPDATE jobs SET status='queued',updated_at=? WHERE status='running'").run(Date.now()); }
 close(){this.#db.close()} get(id:string){const r=this.#db.prepare("SELECT * FROM jobs WHERE id=?").get(id) as Row|undefined; return r&&map(r)} findRequest(id:string){const r=this.#db.prepare("SELECT * FROM jobs WHERE request_id=?").get(id) as Row|undefined;return r&&map(r)}
 createOrGet(input:CreateYoutubeJob){const old=this.findRequest(input.requestId);if(old)return {job:old,created:false};const now=Date.now(),id=randomUUID();this.#db.prepare("INSERT INTO jobs(id,request_id,chat_id,user_id,log_id,url,status,created_at,updated_at) VALUES(?,?,?,?,?,?,'queued',?,?)").run(id,input.requestId,input.chatId,input.userId,input.logId,input.url,now,now);return {job:this.get(id)!,created:true}}
 pending(room:string){return +((this.#db.prepare("SELECT count(*) AS n FROM jobs WHERE chat_id=? AND status IN ('queued','running')").get(room) as {n:number}).n)} next(){const r=this.#db.prepare("SELECT * FROM jobs WHERE status='queued' ORDER BY sequence LIMIT 1").get() as Row|undefined;return r&&map(r)} claim(id:string){const now=Date.now();const x=this.#db.prepare("UPDATE jobs SET status='running',updated_at=? WHERE id=? AND status='queued'").run(now,id);return Number(x.changes)===1?this.get(id):undefined}
 succeed(id:string,a:{path:string;bytes:number;sha256:string}){const now=Date.now();this.#db.prepare("UPDATE jobs SET status='succeeded',artifact_path=?,artifact_bytes=?,artifact_sha256=?,updated_at=?,finished_at=? WHERE id=? AND status='running'").run(a.path,a.bytes,a.sha256,now,now,id)} fail(id:string,code:string){const now=Date.now();this.#db.prepare("UPDATE jobs SET status='failed',error_code=?,updated_at=?,finished_at=? WHERE id=? AND status IN ('queued','running')").run(code,now,now,id)} cancel(id:string){const now=Date.now();const x=this.#db.prepare("UPDATE jobs SET status='cancelled',updated_at=?,finished_at=? WHERE id=? AND status IN ('queued','running')").run(now,now,id);return Number(x.changes)===1} expired(cutoff:number){const rs=this.#db.prepare("SELECT * FROM jobs WHERE finished_at<? AND artifact_path IS NOT NULL").all(cutoff) as unknown as Row[];this.#db.prepare("UPDATE jobs SET artifact_path=NULL,artifact_bytes=NULL,artifact_sha256=NULL WHERE finished_at<?").run(cutoff);return rs.map(map)} }
